// Packages: AWSSDK.S3, AWSSDK.SecretsManager
using Amazon;
using Amazon.S3;
using Amazon.SecretsManager;
using Amazon.SecretsManager.Model;

public static async Task<ListBucketsResponse> ListBucketsWithSecretsAsync(
    string secretId,
    CancellationToken cancellationToken = default)
{
    try
    {
        // Uses default credential chain - works locally and in AWS
        var s3Client = new AmazonS3Client(RegionEndpoint.USEast1);
        var secretsClient = new SecretsManagerClient(RegionEndpoint.USEast1);

        // Retrieve a secret (e.g., database connection string)
        var secretRequest = new GetSecretValueRequest { SecretId = secretId };
        var secretResponse = await secretsClient.GetSecretValueAsync(secretRequest, cancellationToken);
        Console.WriteLine($"Retrieved secret: {secretResponse.SecretString}");

        // List S3 buckets
        ListBucketsResponse response = await s3Client.ListBucketsAsync(cancellationToken);
        foreach (var bucket in response.Buckets)
        {
            Console.WriteLine($"Bucket: {bucket.BucketName} (Created: {bucket.CreationDate:yyyy-MM-dd})");
        }

        return response;
    }
    catch (AmazonS3Exception ex)
    {
        Console.WriteLine($"S3 error: {ex.Message}");
        throw;
    }
    catch (AmazonSecretsManagerException ex)
    {
        Console.WriteLine($"Secrets Manager error: {ex.Message}");
        throw;
    }
}

